    public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("planner_v3",0);getWindow().setStatusBarColor(pale);getWindow().setNavigationBarColor(Color.WHITE);if(Build.VERSION.SDK_INT>=23)getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);if(!prefs.contains("cycle_start")){Calendar c=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);prefs.edit().putLong("cycle_start",c.getTimeInMillis()).apply();}if(!prefs.contains("milk_qty"))prefs.edit().putString("milk_qty","1").apply();if(!prefs.contains("budget"))prefs.edit().putString("budget","8000").apply();if(!prefs.contains("rem_hour"))prefs.edit().putInt("rem_hour",19).putInt("rem_min",0).apply();build();if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=0)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},10);if(prefs.getBoolean("rem_enabled",false))scheduleReminder();}
    GradientDrawable shape(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(24);return d;}
    TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
    LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
    String money(double v){return "₹"+String.format(Locale.US,"%.2f",v);}
    String date(long ms){return new SimpleDateFormat("dd MMM yyyy",Locale.getDefault()).format(new Date(ms));}
    int dayFor(Calendar date){Calendar start=Calendar.getInstance();start.setTimeInMillis(prefs.getLong("cycle_start",System.currentTimeMillis()));start.set(Calendar.HOUR_OF_DAY,0);start.set(Calendar.MINUTE,0);start.set(Calendar.SECOND,0);start.set(Calendar.MILLISECOND,0);Calendar d=(Calendar)date.clone();d.set(Calendar.HOUR_OF_DAY,0);d.set(Calendar.MINUTE,0);d.set(Calendar.SECOND,0);d.set(Calendar.MILLISECOND,0);long diff=(d.getTimeInMillis()-start.getTimeInMillis())/86400000L;if(diff<0)diff=0;return (int)(diff%30);}
    void build(){root=col();root.setBackgroundColor(pale);setContentView(root);root.setOnApplyWindowInsetsListener((v,in)->{int l,t,r,b;if(Build.VERSION.SDK_INT>=30){android.graphics.Insets x=in.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());l=x.left;t=x.top;r=x.right;b=x.bottom;}else{l=in.getSystemWindowInsetLeft();t=in.getSystemWindowInsetTop();r=in.getSystemWindowInsetRight();b=in.getSystemWindowInsetBottom();}root.setPadding(16+l,10+t,16+r,6+b);return in;});root.addView(text("🥥 OORU MEALS  •  2 ADULTS",17,green,true));header=text("",25,ink,true);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(-1,-2);hp.topMargin=12;hp.bottomMargin=10;root.addView(header,hp);ScrollView sc=new ScrollView(this);sc.setFillViewport(false);body=col();sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));nav=new LinearLayout(this);nav.setGravity(Gravity.CENTER);nav.setBackgroundColor(Color.WHITE);nav.setElevation(8);String[] tabs={"Home","Calendar","Shopping","Recipes","Settings"};for(int i=0;i<5;i++){final int p=i;TextView t=text(tabs[i],11,muted,true);t.setGravity(Gravity.CENTER);t.setPadding(1,15,1,15);nav.addView(t,new LinearLayout.LayoutParams(0,-2,1));t.setOnClickListener(v->{page=p;draw();});}root.addView(nav,new LinearLayout.LayoutParams(-1,-2));root.requestApplyInsets();draw();}
    LinearLayout card(String title,String desc){LinearLayout c=col();c.setPadding(15,14,15,14);c.setBackground(shape(Color.WHITE));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=10;body.addView(c,p);c.addView(text(title,16,ink,true));if(desc!=null&&!desc.isEmpty()){TextView d=text(desc,14,muted,false);d.setPadding(0,6,0,0);c.addView(d);}return c;}
    void button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setTextSize(14);b.setBackground(shape(green));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=8;body.addView(b,p);b.setOnClickListener(v->action.run());}
    EditText edit(String value,String hint){EditText e=new EditText(this);e.setSingleLine(true);e.setText(value);e.setHint(hint);e.setTextSize(16);return e;}
    void dialogFields(String title,String[] labels,String[] values,java.util.function.Consumer<String[]> save){LinearLayout box=col();box.setPadding(8,4,8,0);EditText[] fields=new EditText[labels.length];for(int i=0;i<labels.length;i++){box.addView(text(labels[i],13,muted,true));fields[i]=edit(values[i],"Enter "+labels[i]);box.addView(fields[i]);}new AlertDialog.Builder(this).setTitle(title).setView(box).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{String[] v=new String[fields.length];for(int i=0;i<v.length;i++)v[i]=fields[i].getText().toString().trim();save.accept(v);}).show();}
    String mealText(int d){return "Breakfast: "+meals[d][0]+"\nLunch: "+meals[d][1]+"\nDinner: "+meals[d][2];}
    void draw(){body.removeAllViews();String[] titles={"Your meal plan","30-day calendar","Shopping & expenses","Recipes","Settings"};header.setText(titles[page]);for(int i=0;i<5;i++)((TextView)nav.getChildAt(i)).setTextColor(i==page?green:muted);
      if(page==0){Calendar now=Calendar.getInstance();selectedDay=dayFor(now);String today=new SimpleDateFormat("EEEE, dd MMMM yyyy",Locale.getDefault()).format(now.getTime());card(today,"TODAY  •  DAY "+(selectedDay+1)+" OF 30\n"+mealText(selectedDay));int next=(selectedDay+1)%30;card("TOMORROW  •  DAY "+(next+1),mealText(next));if(!reuse[selectedDay].isEmpty())card("COOK ONCE, SAVE TIME",reuse[selectedDay]);double spent=monthSpend();double budget=number(prefs.getString("budget","8000"));card("THIS MONTH'S GROCERY SPENDING", "Spent: "+money(spent)+"\nBudget: "+money(budget)+"\nRemaining: "+money(budget-spent));button("Open calendar",()->{page=1;draw();});button("Open shopping & expenses",()->{page=2;draw();});}
      if(page==1){card("YOUR 30-DAY PLAN","Automatically follows your selected start date. Today is highlighted.");Calendar now=Calendar.getInstance();int today=dayFor(now);for(int i=0;i<30;i++){final int n=i;LinearLayout c=card("DAY "+(i+1)+(i==today?"  •  TODAY":""),mealText(i));if(i==today)c.setBackground(shape(Color.rgb(232,246,237)));Button e=new Button(this);e.setText("Edit this day's menu");e.setAllCaps(false);c.addView(e);e.setOnClickListener(v->editMeal(n));}}
      if(page==2){double spent=monthSpend(),budget=number(prefs.getString("budget","8000"));card("MONTHLY BUDGET", "Budget: "+money(budget)+"\nSpent this month: "+money(spent)+"\nRemaining: "+money(budget-spent)+"\nMilk included: "+prefs.getString("milk_qty","1")+" litre(s) every day");button("Add a grocery purchase",()->choosePurchase());button("Add your own ingredient",()->addIngredient());card("INGREDIENT SHOPPING LIST • 2 ADULTS","Estimated quantities for one 30-day plan. These are editable planning estimates, not quantities stated in your PDF. Add each actual purchase below to build your price history.");JSONArray custom=customIngredients();for(int i=0;i<ingredients.length+custom.length();i++){String name,qty,unit,id;if(i<ingredients.length){name=ingredients[i][0];qty=prefs.getString("qty_"+key(name),ingredients[i][1]);unit=ingredients[i][2];}else{try{JSONObject o=custom.getJSONObject(i-ingredients.length);name=o.getString("name");qty=prefs.getString("qty_"+key(name),o.getString("qty"));unit=o.getString("unit");}catch(Exception ex){continue;}}id=key(name);LinearLayout c=card(name, "Plan quantity: "+qty+" "+unit+"\n"+priceSummary(id));CheckBox tick=new CheckBox(this);tick.setText("Purchased / collected");tick.setChecked(prefs.getBoolean("tick_"+id,false));c.addView(tick);tick.setOnCheckedChangeListener((v,on)->prefs.edit().putBoolean("tick_"+id,on).apply());Button row=new Button(this);row.setText("Edit quantity  •  Add purchase");row.setAllCaps(false);c.addView(row);final String nm=name,un=unit;row.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(nm).setItems(new String[]{"Edit planned quantity","Record purchase"},(dd,which)->{if(which==0)dialogFields("Edit planned quantity",new String[]{"Quantity ("+un+")"},new String[]{prefs.getString("qty_"+id,qty)},a->{prefs.edit().putString("qty_"+id,a[0]).apply();draw();});else recordPurchase(nm,un);}).show());}}
      if(page==3){card("30-DAY RECIPE INDEX","The supplied PDF lists meal names and leftover notes; it does not contain measured recipes or cooking steps. Edit any dish in Calendar.");for(int i=0;i<30;i++)card("DAY "+(i+1),meals[i][0]+"\n"+meals[i][1]+"\n"+meals[i][2]);}
      if(page==4){card("PLAN START DATE","Current cycle starts: "+date(prefs.getLong("cycle_start",System.currentTimeMillis()))+"\nDay number follows the real phone date and repeats every 30 days.");button("Change plan start date",()->pickStartDate());card("DAILY MILK","Current daily quantity: "+prefs.getString("milk_qty","1")+" litre(s). Default is 1 litre per day for two adults.");button("Change daily milk quantity",()->dialogFields("Daily milk quantity",new String[]{"Litres per day"},new String[]{prefs.getString("milk_qty","1")},a->{prefs.edit().putString("milk_qty",a[0]).apply();draw();}));card("MONTHLY GROCERY BUDGET","Current budget: "+money(number(prefs.getString("budget","8000"))));button("Change monthly budget",()->dialogFields("Monthly budget",new String[]{"Budget in rupees"},new String[]{prefs.getString("budget","8000")},a->{prefs.edit().putString("budget",a[0]).apply();draw();}));int h=prefs.getInt("rem_hour",19),m=prefs.getInt("rem_min",0);card("DAILY NOTIFICATION","Reminder time: "+String.format(Locale.US,"%02d:%02d",h,m)+"\nNotification previews tomorrow's meals and reminds you to check groceries.");button("Change notification time",()->new TimePickerDialog(this,(v,hh,mm)->{prefs.edit().putInt("rem_hour",hh).putInt("rem_min",mm).putBoolean("rem_enabled",true).apply();scheduleReminder();draw();},h,m,true).show());button(prefs.getBoolean("rem_enabled",false)?"Turn daily reminder off":"Turn daily reminder on",()->{boolean on=!prefs.getBoolean("rem_enabled",false);prefs.edit().putBoolean("rem_enabled",on).apply();if(on)scheduleReminder();else cancelReminder();draw();});button("Reset reminder time to 7:00 PM",()->{prefs.edit().putInt("rem_hour",19).putInt("rem_min",0).putBoolean("rem_enabled",true).apply();scheduleReminder();draw();});card("YOUR FOOD PLAN RULES","No upma, pongal, appam, idiyappam or evening snacks. Poha and variety rice included. Poori and chapati on weekends only. Lunch leftovers are reused where noted in your PDF.");card("LEFTOVER SAFETY","Refrigerate cooked rice and curries promptly (within 1 hour in hot weather). Do not leave cooked rice at room temperature until dinner. Reheat thoroughly.");}
    }
    void editMeal(int d){dialogFields("Edit Day "+(d+1),new String[]{"Breakfast","Lunch","Dinner"},meals[d],a->{for(int i=0;i<3;i++)meals[d][i]=a[i];for(int i=0;i<3;i++)prefs.edit().putString("meal_"+d+"_"+i,a[i]).apply();draw();});}
    void loadEdits(){for(int d=0;d<30;d++)for(int i=0;i<3;i++){String x=prefs.getString("meal_"+d+"_"+i,null);if(x!=null)meals[d][i]=x;}}
    double number(String s){try{return Double.parseDouble(s);}catch(Exception e){return 0;}}
    String key(String s){return s.toLowerCase(Locale.US).replaceAll("[^a-z0-9]+","_");}
    JSONArray customIngredients(){try{return new JSONArray(prefs.getString("custom_ingredients","[]"));}catch(Exception e){return new JSONArray();}}
    void addIngredient(){dialogFields("Add ingredient",new String[]{"Ingredient name","Planned quantity","Unit"},new String[]{"","","kg"},a->{if(a[0].isEmpty())return;JSONArray ar=customIngredients();JSONObject o=new JSONObject();try{o.put("name",a[0]);o.put("qty",a[1]);o.put("unit",a[2]);ar.put(o);prefs.edit().putString("custom_ingredients",ar.toString()).apply();}catch(Exception e){}draw();});}
    JSONArray purchases(String id){try{return new JSONArray(prefs.getString("purchases_"+id,"[]"));}catch(Exception e){return new JSONArray();}}
    String priceSummary(String id){JSONArray a=purchases(id);if(a.length()==0)return "No purchase price recorded yet";try{JSONObject last=a.getJSONObject(a.length()-1);double p=last.optDouble("unitPrice",0);String s="Latest: "+money(p)+" per unit";if(a.length()>1){double prev=a.getJSONObject(a.length()-2).optDouble("unitPrice",p);double diff=p-prev;s+="\nPrevious: "+money(prev)+"  •  "+(diff>0?"↑ ":"↓ ")+money(Math.abs(diff));}return s;}catch(Exception e){return "No price history";}}
    void choosePurchase(){ArrayList<String> names=new ArrayList<>();for(String[] x:ingredients)names.add(x[0]);JSONArray c=customIngredients();for(int i=0;i<c.length();i++)names.add(c.optJSONObject(i).optString("name"));new AlertDialog.Builder(this).setTitle("Choose ingredient").setItems(names.toArray(new String[0]),(d,w)->{String name=names.get(w),unit="unit";for(String[] x:ingredients)if(x[0].equals(name))unit=x[2];if(w>=ingredients.length)unit=c.optJSONObject(w-ingredients.length).optString("unit","unit");recordPurchase(name,unit);}).show();}
    void recordPurchase(String name,String unit){String id=key(name);dialogFields("Record purchase: "+name,new String[]{"Quantity purchased ("+unit+")","Total amount paid (₹)"},new String[]{"1",""},a->{double q=number(a[0]),total=number(a[1]);if(q<=0||total<=0){Toast.makeText(this,"Enter a valid quantity and amount",Toast.LENGTH_LONG).show();return;}JSONArray ar=purchases(id);JSONObject o=new JSONObject();try{o.put("date",new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date()));o.put("qty",q);o.put("total",total);o.put("unitPrice",total/q);ar.put(o);prefs.edit().putString("purchases_"+id,ar.toString()).putBoolean("tick_"+id,true).apply();Toast.makeText(this,"Purchase saved",Toast.LENGTH_SHORT).show();draw();}catch(Exception e){}});}
    double monthSpend(){String month=new SimpleDateFormat("yyyy-MM",Locale.US).format(new Date());double sum=0;try{for(Map.Entry<String,?> en:prefs.getAll().entrySet())if(en.getKey().startsWith("purchases_")){JSONArray a=new JSONArray(String.valueOf(en.getValue()));for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);if(o.optString("date").startsWith(month))sum+=o.optDouble("total",0);}}}catch(Exception e){}return sum;}
    void pickStartDate(){Calendar c=Calendar.getInstance();c.setTimeInMillis(prefs.getLong("cycle_start",System.currentTimeMillis()));new DatePickerDialog(this,(v,y,m,d)->{Calendar x=Calendar.getInstance();x.set(y,m,d,0,0,0);x.set(Calendar.MILLISECOND,0);prefs.edit().putLong("cycle_start",x.getTimeInMillis()).apply();draw();},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show();}
    void scheduleReminder(){AlarmManager a=(AlarmManager)getSystemService(ALARM_SERVICE);Intent i=new Intent(this,ReminderReceiver.class);PendingIntent p=PendingIntent.getBroadcast(this,1,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Calendar c=Calendar.getInstance();c.set(Calendar.HOUR_OF_DAY,prefs.getInt("rem_hour",19));c.set(Calendar.MINUTE,prefs.getInt("rem_min",0));c.set(Calendar.SECOND,0);if(c.getTimeInMillis()<=System.currentTimeMillis())c.add(Calendar.DATE,1);if(Build.VERSION.SDK_INT>=23)a.setInexactRepeating(AlarmManager.RTC_WAKEUP,c.getTimeInMillis(),AlarmManager.INTERVAL_DAY,p);else a.setRepeating(AlarmManager.RTC_WAKEUP,c.getTimeInMillis(),AlarmManager.INTERVAL_DAY,p);Toast.makeText(this,"Daily reminder saved",Toast.LENGTH_SHORT).show();}
    void cancelReminder(){((AlarmManager)getSystemService(ALARM_SERVICE)).cancel(PendingIntent.getBroadcast(this,1,new Intent(this,ReminderReceiver.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));}
    @Override protected void onResume(){super.onResume();if(prefs!=null){loadEdits();if(body!=null)draw();}}
